{
  "planId": "d83b4a0d-8ae8-477d-8444-1d26b002fb14",
  "operations": [
    {
      "id": "op-1",
      "kind": "create",
      "target": "Components/StockItemRow",
      "intent": "A single row in the stock list: shows item name, count, supplier. Out-of-stock items (count=0) get a red highlight. Includes +/- buttons to adjust count and a delete button.",
      "inputs": [
        {
          "name": "name",
          "type": "string",
          "description": "The item name"
        },
        {
          "name": "count",
          "type": "number",
          "description": "How many are left"
        },
        {
          "name": "supplier",
          "type": "string",
          "description": "Who supplies it"
        },
        {
          "name": "itemId",
          "type": "string",
          "description": "The record objectId for updates"
        }
      ],
      "outputs": [
        {
          "name": "countChanged",
          "type": "signal",
          "description": "Fires when count was incremented or decremented"
        },
        {
          "name": "itemDeleted",
          "type": "signal",
          "description": "Fires when the item was deleted"
        }
      ]
    },
    {
      "id": "op-2",
      "kind": "create",
      "target": "Components/AddStockForm",
      "intent": "A form with name, count, and supplier fields plus an Add button. Creates a new StockItem record on submit.",
      "outputs": [
        {
          "name": "itemAdded",
          "type": "signal",
          "description": "Fires after a new item is created"
        }
      ]
    },
    {
      "id": "op-3",
      "kind": "create",
      "target": "Pages/StockCupboard",
      "intent": "The main stock cupboard page. Shows sign-in/sign-up when not authenticated. When signed in, shows who is signed in, the stock list (using StockItemRow for each item), and the AddStockForm. Queries StockItem from the backend.",
      "instantiates": [
        "Components/StockItemRow",
        "Components/AddStockForm"
      ]
    }
  ],
  "scroll": "page",
  "note": "Nothing is written yet. Stage every operation with stage_plan_operation (in the order given — creates first, so updates can instantiate them; docs last, so you write them knowing what the components ended up being), then apply_plan."
}

