            "scrollEnabled": true
          },
          "children": [
            "task_repeater"
          ]
        },
        {
          "id": "task_repeater",
          "type": "For Each",
          "label": "One card per task",
          "parent": "list_group",
          "parameters": {
            "template": "/Task Card"
          }
        },
        {
          "id": "tasks_query",
          "type": "DbCollection2",
          "label": "Fetch tasks",
          "parameters": {
            "collectionName": "Task"
          }
        }
      ],
      "connections": [
        {
          "fromId": "tasks_query",
          "fromProperty": "items",
          "toId": "task_repeater",
          "toProperty": "items"
        }
